#include <stdio.h>
#include <string.h>

static char keypad(char c) {
    if (c >= 'a' && c <= 'c') return '2';
    if (c >= 'd' && c <= 'f') return '3';
    if (c >= 'g' && c <= 'i') return '4';
    if (c >= 'j' && c <= 'l') return '5';
    if (c >= 'm' && c <= 'o') return '6';
    if (c >= 'p' && c <= 's') return '7';
    if (c >= 't' && c <= 'v') return '8';
    return '9';
}

int main(void) {
    char N[1005], C[1005];
    int M;

    if (scanf("%1004s", N) != 1) return 0;
    scanf("%d", &M);

    int lenN = (int)strlen(N);
    int answer = 0;

    for (int i = 0; i < M; i++) {
        scanf("%1004s", C);

        if ((int)strlen(C) != lenN) continue;

        int ok = 1;
        for (int j = 0; j < lenN; j++) {
            if (keypad(C[j]) != N[j]) {
                ok = 0;
                break;
            }
        }

        if (ok) answer++;
    }

    printf("%d\n", answer);
    return 0;
}
